import React, { useState, useEffect } from "react";
import { useNavigate, useParams } from "react-router-dom";
import ScheduleTable from "../../components/ScheduleTable/ScheduleTable";
import OrarStudenti from './OrarStudenti';  
import OrarProfesori from './OrarProfesori';  
import OrarDiscipline from './OrarDiscipline';  
import OrarSali from './OrarSali';  
import "./OrarToti.css";

const OrarToti = () => {
  const navigate = useNavigate();
  const { an, grupa, section, profesor } = useParams();

  const [selectedGroup, setSelectedGroup] = useState(null);
  const [scheduleData, setScheduleData] = useState([]);
  const [currentSection, setCurrentSection] = useState(section || null);
  const [selectedProfessor, setSelectedProfessor] = useState(profesor || null); // Răspuns corect la profesorul selectat

  // Actualizează când an și grupa sunt disponibile
  useEffect(() => {
    if (an && grupa) {
      const anLabel = `Anul ${an}`;
      setSelectedGroup(`${anLabel} - ${grupa}`);
      setCurrentSection("studenti");

      const url = `http://localhost:34101/orar/grupa/${an}/${grupa}`;
      fetch(url)
        .then((res) => res.json())
        .then((data) => {
          setScheduleData(data);
        })
        .catch((err) => {
          console.error("Eroare la preluarea orarului:", err);
        });
    }
  }, [an, grupa]);

  // Preia orarul unui profesor selectat
  useEffect(() => {
    if (selectedProfessor) {
      const url = `http://localhost:34101/orar/profesor/${selectedProfessor}`;
      fetch(url)
        .then((res) => res.json())
        .then((data) => {
          setScheduleData(data);
        })
        .catch((err) => {
          console.error("Eroare la preluarea orarului profesorului:", err);
        });
    }
  }, [selectedProfessor]);

  // Navighează înapoi la secțiunea principală
  const handleBackButtonClick = () => {
    setSelectedGroup(null);
    setSelectedProfessor(null); // Resetează profesorul selectat
    setScheduleData([]);
    navigate(`/app/orar/${currentSection}`);  // Navighează doar la secțiunea respectivă
  };

  // Navighează la altă secțiune
  const handleSectionChange = (newSection) => {
    setCurrentSection(newSection);
    navigate(`/app/orar/${newSection}`);
  };

  return (
    <div className="orar-container">
      {selectedGroup || selectedProfessor ? (
        <div className="orar-afisat">
          <h3>
            Orar pentru {selectedGroup || `Profesor ${selectedProfessor}`}
          </h3>
          <ScheduleTable
            schedule={scheduleData}
            title={`Orar pentru ${selectedGroup || `Profesor ${selectedProfessor}`}`}
          />
          <button
            className="orar-button inapoi"
            onClick={handleBackButtonClick}
          >
            🔙 Înapoi
          </button>
        </div>
      ) : (
        <>
          <div className="orar-titlu">
            <h1>Orar</h1>
            {!currentSection && <h2>Alege o categorie</h2>}
            {currentSection === "studenti" && <h2>Alege anul și grupa</h2>}
          </div>

          {!currentSection && (
            <div className="orar-buttons">
              <button
                className="orar-button"
                onClick={() => handleSectionChange("studenti")}
              >
                🎓 Orar Studenți
              </button>
              <button
                className="orar-button"
                onClick={() => handleSectionChange("profesori")}
              >
                👨‍🏫 Orar Profesori
              </button>
              <button
                className="orar-button"
                onClick={() => handleSectionChange("sali")}
              >
                🏫 Orar Săli
              </button>
              <button
                className="orar-button"
                onClick={() => handleSectionChange("discipline")}
              >
                📚 Orar Discipline
              </button>
            </div>
          )}

          {currentSection === "studenti" && (
            <>
              <div className="orar-buttons">
                <button
                  className="orar-button inapoi"
                  onClick={handleBackButtonClick}
                >
                  🔙 Înapoi la Orar
                </button>
              </div>
              <OrarStudenti />
            </>
          )}
          {currentSection === "profesori" && (
            <OrarProfesori onProfessorClick={(professorName) => setSelectedProfessor(professorName)} />
          )}
          {currentSection === "discipline" && <OrarDiscipline />}
          {currentSection === "sali" && <OrarSali />}
        </>
      )}
    </div>
  );
};

export default OrarToti;
